import { useEffect, useState } from "react";
import { useNavigate } from "react-router-dom";
import api from "../api";

export default function Candidates() {
  const [candidates, setCandidates] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    const fetchCandidates = async () => {
      try {
        const res = await api.get("/candidates");
        setCandidates(res.data);
      } catch (err) {
        setError(err.response?.data?.error || "Failed to load candidates");
      } finally {
        setLoading(false);
      }
    };
    fetchCandidates();
  }, []);

  if (loading) return <p className="text-center mt-10">Loading candidates...</p>;
  if (error) return <p className="text-center mt-10 text-red-600">{error}</p>;

  return (
    <div className="p-6">
      <h1 className="text-2xl font-bold mb-6">Candidates</h1>
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        {candidates.map((c) => (
          <div
            key={c.id}
            className="bg-white rounded-2xl shadow-md p-4 flex flex-col items-center"
          >
            <h2 className="text-xl font-semibold">{c.name}</h2>
            <p className="text-gray-600">{c.position}</p>
            <button
              onClick={() => navigate("/vote", { state: { candidate: c } })}
              className="mt-4 bg-blue-600 text-white px-4 py-2 rounded-xl hover:bg-blue-700"
            >
              Vote
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}
